llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Isotretinoin, a retinoid sharing the same cyclohexene/tetraene scaffold as the query, has a systemic bioavailability of 40% in patients, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Etretinate, a highly lipophilic aromatic retinoid with very low aqueous solubility, has an absolute oral bioavailability of about 40% in healthy volunteers, showing that lipophilic retinoids can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Acitretin, the active metabolite of etretinate, has an absolute bioavailability of 60% (range 36-95%) in 12 subjects, further supporting moderate-to-good oral bioavailability for retinoid-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Acetaminophen, which shares the p-hydroxyanilide substructure with the query, has an absolute oral bioavailability of 87% in fasted healthy volunteers, indicating the amide-phenol head group is not an absorption barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Teriflunomide, another anilide-containing drug, has absolute oral bioavailability approaching 100% in fasted healthy subjects, supporting that anilide molecules can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Lutein, a highly lipophilic carotenoid, reached 55% oral bioavailability in humans when formulated appropriately, showing that polyene lipids can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Norbixin, a polyene dicarboxylic acid, showed reproducible 43% oral bioavailability from a powder-filled capsule in animals and humans, supporting moderate F for long polyene retinoid-like molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a retinoyl p-hydroxyanilide (fenretinide-like). Multiple high-transfer retinoid analogs (isotretinoin 40%, etretinate 40%, acitretin 60%) and the p-hydroxyanilide substructure (acetaminophen 87%) support F >= 20%. The only low-bioavailability evidence (tocotrienols) has zero transferability and is not applicable. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide itself in the provided evidence.",
    "Food effect and formulation dependence for the query are unknown; several supportive data were obtained with lipid-rich vehicles or specific formulations.",
    "First-pass metabolism of the phenolic amide (e.g., glucuronidation) is not directly quantified for the full retinoid structure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

